# Those are linker veneer patches. Let me look at dynamic symbols instead
DBGFILE="/tmp/libmonosgen-2.0.so.dbg"
nm -D -n "$DBGFILE" 2>/dev/null | grep -E " [TtWw] " | awk '
{
  val = strtonum("0x" $1)
  if (val <= 0x2f4b20) { fn1_addr = val; fn1_name = $3 }
  if (val <= 0x2f4c84) { fn2_addr = val; fn2_name = $3 }
  if (val <= 0x2c1a40) { fn3_addr = val; fn3_name = $3 }
}
END {
  printf "0x2f4b20 is in: %s (base 0x%x, offset +0x%x)\n", fn1_name, fn1_addr, 0x2f4b20-fn1_addr
  printf "0x2f4c84 is in: %s (base 0x%x, offset +0x%x)\n", fn2_name, fn2_addr, 0x2f4c84-fn2_addr
  printf "0x2c1a40 is in: %s (base 0x%x, offset +0x%x)\n", fn3_name, fn3_addr, 0x2c1a40-fn3_addr
}'

