arguments.command:
# Let me look at the DWARF info directly for these addresses
DBGFILE="/tmp/libmonosgen-2.0.so.dbg"
# Use readelf to find .debug_info, or try objdump with source
addr2line -f -e "$DBGFILE" --section=.text 0x2f4b20 0x2f4c84 2>/dev/null
echo "---"
# The SGen worker addresses might be in .bss or data. Let me check what section they're in
readelf -S "$DBGFILE" 2>/dev/null | grep -E "^\s+\[" | awk '{
  if (NF > 5) {
    name=$2; addr=$4; offset=$5; size=$6
    if (name != "" && addr != "") printf "%s %s %s\n", name, addr, size
  }
}' | head -30
echo "==="
# Actually these might be in .bss. The nm output showed 'b' (BSS) for those $d symbols
# These aren't code addresses - they're data. The thread is likely waiting in a condition variable
# and the "pc" is actually pointing at data used by the SGen GC
# Let me check if there are function symbols that contain these
nm "$DBGFILE" 2>/dev/null | grep -E " [Tt] " | sort | awk '
{
  val = strtonum("0x" $1)
  if (val <= 0x2f4b20 && val > prev1) { prev1 = val; fn1 = $3 }
  if (val <= 0x2f4c84 && val > prev2) { prev2 = val; fn2 = $3 }
}
END {
  printf "0x2f4b20 nearest function: %s at 0x%x\n", fn1, prev1
  printf "0x2f4c84 nearest function: %s at 0x%x\n", fn2, prev2
}'

