  val = strtonum("0x" $2)
  size = strtonum($3)
  name = $8
  if (val <= 0x2f4b20 && val+size > 0x2f4b20) printf "0x2f4b20 in: %s (0x%x - 0x%x)\n", name, val, val+size
  if (val <= 0x2f4c84 && val+size > 0x2f4c84) printf "0x2f4c84 in: %s (0x%x - 0x%x)\n", name, val, val+size
}'", "description": "Find functions by size range"}
